"""SYNTHETIC DEVELOPMENT CORPUS: clearly labelled, generated by templates, NOT human data.

Why it exists: the repository contains no persona/response dataset (the datasets named in the
old README were never included), and a from-scratch model needs *some* persona-conditioned
text to learn from. This module composes responses from hand-written phrase banks so that
the content depends on the persona:

    stance        <- political lean (political/social issues) or Big-5 profile (economic/health)
    value lines   <- political lean, phrased for the scenario domain; more of them the further
                     the persona is from the political centre
    trait lines   <- one line per clearly high/low Big-5 trait
    style         <- communication-style family (terse / analytical / formal / expressive / warm)
    detail        <- occupation (individual, not a demographic stereotype)

It is a *development* dataset: good enough to verify that the pipeline learns persona
conditioning and that feedback training changes behaviour. Replace / extend it with real
data via ``data/ingestion.py`` for research claims about real people.
"""
from __future__ import annotations

import random
import re

from twin.persona_serializer import lean, level
from twin.personas import TRAITS, sample_persona
from twin.scenarios import scenarios_by_split

DATASET_NAME = "synthetic-dev"
DATASET_VERSION = "synthetic-dev-v1"


# --------------------------------------------------------------------------- stance keys
def stance_key(kind: str, p: dict) -> str:
    O, C, E, A, N = (level(p[t]) for t in TRAITS)
    if kind == "lean":
        return lean(p["political"])
    if kind == "econ":
        if C == "high":
            return "careful"
        if O == "high" and N != "high":
            return "bold"
        if C == "low":
            return "spend"
        return "balanced"
    if kind == "health":
        if N == "high" or (C == "high" and O == "low"):
            return "cautious"
        if O == "high" and A != "low":
            return "open"
        if A == "low" or O == "low":
            return "skeptical"
        return "balanced"
    if kind == "social":
        if A == "low":
            return "confront"
        if E == "low":
            return "ignore"
        if A == "high":
            return "gentle"
        return "comment"
    raise ValueError(kind)


DOMAIN_KEY = {"economic": "econ", "political": "lean", "health": "health"}
SOCIAL_LEAN_ISSUES = {"traditional_values", "viral_climate_post", "remote_work_post", "local_news_post"}


def issue_key_kind(issue: str, domain: str) -> str:
    if domain == "social":
        return "lean" if issue in SOCIAL_LEAN_ISSUES else "social"
    return DOMAIN_KEY[domain]


