ANALYTICAL_LINES = ["The data on this is mixed, so I'd weigh the numbers.", "On balance, the evidence points that way.",
                    "Roughly speaking, the trade-off seems worth it.", "I'd want to see the numbers before committing."]
WARM_LINES = ["I understand this is hard for a lot of people.", "I hope everyone involved is okay.",
              "I care about how this affects the people around me.", "We should be kind to each other about it."]
EXPRESSIVE_OPENERS = ["Honestly!", "Okay, real talk.", "Oh wow.", "Seriously,", "Lol,"]
FORMAL_CLOSERS = ["Thank you.", "That is my considered view.", "I say this with respect."]
HEDGES = ["I think", "It seems", "Probably", "In my estimate,"]

CONTRACTIONS = {"I'd": "I would", "I'm": "I am", "don't": "do not", "doesn't": "does not", "isn't": "is not",
                "wasn't": "was not", "it's": "it is", "It's": "It is", "can't": "cannot", "won't": "will not",
                "I'll": "I will", "let's": "let us", "Let's": "Let us", "they're": "they are", "There's": "There is",
                "there's": "there is", "we've": "we have", "We've": "We have", "aren't": "are not",
                "Don't": "Do not", "didn't": "did not", "that's": "that is", "That's": "That is",
                "I've": "I have", "you're": "you are", "We're": "We are", "we're": "we are"}


def _expand(s: str) -> str:
    for k, v in CONTRACTIONS.items():
        s = re.sub(rf"\b{re.escape(k)}\b", v, s)
    return s


def generate_response(p: dict, scenario: dict, style: str, rng: random.Random) -> str:
    issue, domain = scenario["issue"], scenario["domain"]
    kind = issue_key_kind(issue, domain)
    key = stance_key(kind, p)
    bank = STANCES[issue]
    stance = rng.choice(bank.get(key) or bank[next(iter(bank))])
    values = VALUE_LINES[(domain, lean(p["political"]))]
    extremity = abs(p["political"] - 50)
    # degree of political expression grows with how far the persona is from the centre
    n_values = 2 if extremity > 32 and rng.random() < 0.6 else 1 if extremity > 18 or rng.random() < 0.6 else 0
    if lean(p["political"]) == "center":
        n_values = 1
    picked = rng.sample(values, min(n_values, len(values)))

    trait_lines = []
    for t in TRAITS:
        lv = level(p[t])
        if lv != "mid" and rng.random() < 0.75:
            trait_lines.append(rng.choice(TRAIT_LINES[(t, lv)]))
    rng.shuffle(trait_lines)

    if style == "terse":
        body = [stance] + picked[:1] + trait_lines[:2]
        body = [re.sub(r"^(Honestly|Frankly), ", "", s) for s in body]
        return " ".join(body)

    body = []
    if rng.random() < 0.3 and p.get("occupation"):
        body.append(f"As a {p['occupation']}, I think about this a lot.")
    body.append(stance)
    body.extend(trait_lines[:3])
    for v in picked:
        body.insert(min(len(body), 2 + rng.randint(0, 1)), v)
    if style == "analytical":
        body.insert(1, rng.choice(ANALYTICAL_LINES))
        if not body[0].startswith("As a"):
            first = body[0] if re.match(r"^I\b", body[0]) else body[0][0].lower() + body[0][1:]
            body[0] = f"{rng.choice(HEDGES)} {first}"
    elif style == "warm":
        body.append(rng.choice(WARM_LINES))
    elif style == "expressive":
        body.insert(0, rng.choice(EXPRESSIVE_OPENERS))
        body = [s[:-1] + "!" if s.endswith(".") and rng.random() < 0.5 else s for s in body]
    elif style == "formal":
        body = [_expand(s) for s in body]
        body.append(rng.choice(FORMAL_CLOSERS))
    return " ".join(body)


# --------------------------------------------------------------------------- corpus building
def persona_bio(p: dict) -> str:
    return (f"{p['label']} is a {p['age']}-year-old {p['gender']} {p['occupation']} from {p['location']}. "
            f"They are {level(p['openness'])} in openness, {level(p['conscientiousness'])} in conscientiousness, "
            f"{level(p['extraversion'])} in extraversion, {level(p['agreeableness'])} in agreeableness and "
            f"{level(p['neuroticism'])} in neuroticism, with {lean(p['political'])}-leaning politics. "
            f"Economically they are {p['economic']}. They speak in a way that is {p['commStyle']}.")


def build_persona_examples(n: int, split: str, seed: int) -> list[dict]:
    """Persona-conditioned (persona, scenario, response) triples for the given scenario split."""
    rng = random.Random(seed)
    scen = scenarios_by_split(split)
    out = []
    for _ in range(n):
        p, style = sample_persona(rng)
        s = rng.choice(scen)
        out.append({"persona": p, "scenario": s, "response": generate_response(p, s, style, rng),
                    "style_family": style, "source": "synthetic"})
    return out


def build_pretraining_texts(n_docs: int, seed: int) -> list[str]:
    """Stage-1 'general language' documents: bios, scenario texts and responses as plain prose
    (no persona tags). Only the *train* scenario split is used."""
    rng = random.Random(seed)
    scen = scenarios_by_split("train")
    docs = []
    for _ in range(n_docs):
        p, style = sample_persona(rng)
        s = rng.choice(scen)
        r = rng.random()
        if r < 0.3:
            docs.append(persona_bio(p))
        elif r < 0.45:
            docs.append(s["text"])
        else:
            docs.append(f"Question: {s['text']} Answer: {generate_response(p, s, style, rng)}")
    return docs
